    def omega_ratio(
        self, *, returns: list[float] | list[list[float]], threshold: float = 0.0
    ) -> dict[str, Any]:
        """Omega ratio — probability-weighted gains over losses about a threshold.

        ``Omega = sum(max(r - threshold, 0)) / sum(max(threshold - r, 0))``.

        Returns:
            The raw API response as a dict.
        """
        body = {"returns": returns, "threshold": threshold}
        return self._client._request("POST", "/api/v1/portfolio/omega_ratio", json_body=body)

    def portfolio_beta(
        self,
        *,
        returns: list[float] | list[list[float]],
        benchmark_returns: list[float] | list[list[float]],
    ) -> dict[str, Any]:
        """Portfolio beta — sensitivity of portfolio returns to the benchmark.

        ``beta = cov(r, b) / var(b)``.

        Returns:
            The raw API response as a dict.
        """
        body = {"returns": returns, "benchmark_returns": benchmark_returns}
        return self._client._request("POST", "/api/v1/portfolio/portfolio_beta", json_body=body)

    def portfolio_turnover(
        self,
        *,
        weights_before: list[float] | list[list[float]],
        weights_after: list[float] | list[list[float]],
    ) -> dict[str, Any]:
        """Portfolio turnover — one-way traded fraction between two weight vectors.

        ``0.5 * sum(|w_after - w_before|)`` (one-way convention).

        Returns:
            The raw API response as a dict.
        """
        body = {"weights_before": weights_before, "weights_after": weights_after}
        return self._client._request("POST", "/api/v1/portfolio/portfolio_turnover", json_body=body)

